#define _USE_MATH_DEFINES

#include <cmath>
#include <cstdio>
#include <queue>
#include <algorithm>
#include <functional>
#include <iostream>
#include <iterator>
#include <list>
#include <map>
#include <set>
#include <stack>
#include <string>
#include <vector>

using namespace std;

#define mp make_pair
#define pb push_back

char gridA[12][12];
char gridB[12][12];
int n, T;
bool _dp[70][12][12][12][12];
bool reach[12][12][12][12];
int dist[12][12];

struct State {
    int tt, x, y, x0, y0;
};

void computeReach(int sx, int sy) {
    if (T >= 70) return;
    if (gridA[sx][sy] < '0' || gridA[sx][sy] > '9') return;
    queue<State> q;
    q.push({0, sx, sy, sx, sy});
    _dp[0][sx][sy][sx][sy] = true;
    if (0 <= T) reach[sx][sy][sx][sy] = true;
    while (!q.empty()) {
        State cur = q.front(); q.pop();
        int tt = cur.tt, x = cur.x, y = cur.y, x0 = cur.x0, y0 = cur.y0;
        if (tt > T+1) continue;
        if (tt < dist[x][y]) {
            int ntt = tt + 1;
            if (ntt > T+1) continue;
            // same cell
            int nx = x, ny = y;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                gridA[nx][ny] >= '0' && gridA[nx][ny] <= '9' &&
                !(ntt > dist[nx][ny] && dist[nx][ny] != 0) &&
                !(ntt == dist[nx][ny] && dist[nx][ny] != 0 && (gridB[nx][ny] > '9' || gridB[nx][ny] <= '0')) &&
                !_dp[ntt][nx][ny][x0][y0]) {
                _dp[ntt][nx][ny][x0][y0] = true;
                if (ntt <= T) reach[nx][ny][x0][y0] = true;
                q.push({ntt, nx, ny, x0, y0});
            }
            // neighbors
            int dx[] = {1, -1, 0, 0};
            int dy[] = {0, 0, 1, -1};
            for (int d = 0; d < 4; d++) {
                nx = x + dx[d];
                ny = y + dy[d];
                if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                if (gridA[nx][ny] < '0' || gridA[nx][ny] > '9') continue;
                if (ntt > dist[nx][ny] && dist[nx][ny] != 0) continue;
                if (ntt == dist[nx][ny] && dist[nx][ny] != 0 && (gridB[nx][ny] > '9' || gridB[nx][ny] <= '0')) continue;
                if (_dp[ntt][nx][ny][x0][y0]) continue;
                _dp[ntt][nx][ny][x0][y0] = true;
                if (ntt <= T) reach[nx][ny][x0][y0] = true;
                q.push({ntt, nx, ny, x0, y0});
            }
        }
    }
}

vector<vector<int> > G;
int F[210][210];
int E[210], H[210];
int C[210][210];
int nodeB[11][11];

int main() {
#ifndef ONLINE_JUDGE
    freopen( "1.txt", "rt", stdin );
#endif

    scanf("%d %d", &n, &T);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf(" %c", &gridA[i][j]);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf(" %c", &gridB[i][j]);

    // BFS for distances
    queue<pair<int,int> > q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            dist[i][j] = -1;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (gridA[i][j] == 'Z') {
                dist[i][j] = 0;
                q.push(mp(i,j));
            }
    int di[] = {-1, 0, 1, 0};
    int dj[] = {0, -1, 0, 1};
    while (!q.empty()) {
        pair<int,int> p = q.front(); q.pop();
        if (dist[p.first][p.second] >= T) continue;
        for (int d = 0; d < 4; d++) {
            int ni = p.first + di[d];
            int nj = p.second + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n &&
                gridA[ni][nj] >= '0' && gridA[ni][nj] <= '9' && dist[ni][nj] == -1) {
                dist[ni][nj] = dist[p.first][p.second] + 1;
                q.push(mp(ni,nj));
            }
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (dist[i][j] == -1)
                dist[i][j] = T;

    // Compute reachability
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (gridA[i][j] >= '0' && gridA[i][j] <= '9')
                computeReach(i, j);

    // Build graph
    vector<int> st;
    G.pb(st);
    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            if (gridA[i1][j1] > '0' && gridA[i1][j1] <= '9') {
                int k = G.size();
                vector<int> g;
                G.push_back(g);
                E[k] = gridA[i1][j1] - '0';
                for (int i2 = 0; i2 < n; i2++)
                    for (int j2 = 0; j2 < n; j2++)
                        if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9')
                        if (reach[i2][j2][i1][j1]) {
                            int _k;
                            if (nodeB[i2][j2] == 0) {
                                vector<int> _g;
                                _k = G.size();
                                G.push_back(_g);
                                nodeB[i2][j2] = _k;
                            } else {
                                _k = nodeB[i2][j2];
                            }
                            G[k].pb(_k);
                            G[_k].pb(k);
                            C[k][_k] = 10000;
                            C[_k][k] = 0;
                        }
            }
    for (int i2 = 0; i2 < n; i2++)
        for (int j2 = 0; j2 < n; j2++)
            if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && nodeB[i2][j2] > 0) {
                int _k = nodeB[i2][j2];
                G[_k].push_back(0);
                C[_k][0] = gridB[i2][j2] - '0';
                C[0][_k] = 0;
            }

    // Push-relabel (same as variant 1)
    while (true) {
        bool ff = true;
        for (int i = 1; i < (int)G.size(); i++) {
            while (E[i] > 0) {
                bool f = true;
                int minH = 10000;
                for (int _j = 0; _j < (int)G[i].size(); _j++) {
                    int j = G[i][_j];
                    if (C[i][j] - F[i][j]) minH = min(minH, H[j]);
                    if (C[i][j] - F[i][j] > 0 && H[i] == H[j] + 1) {
                        int d = min(C[i][j] - F[i][j], E[i]);
                        F[i][j] += d;
                        F[j][i] -= d;
                        E[i] -= d;
                        E[j] += d;
                        f = false;
                        ff = false;
                        if (E[i] == 0) break;
                    }
                }
                if (E[i] == 0) break;
                if (H[i] != minH + 1 && minH != 10000) {
                    f = false;
                    ff = false;
                    H[i] = minH + 1;
                }
                if (f) break;
            }
        }
        if (ff) break;
    }

    printf("%d\n", E[0]);
    return 0;
}
